package dev.aivillages.core.kernel;
import java.util.*;
import java.nio.file.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static dev.aivillages.core.kernel.Contracts.*;
import static dev.aivillages.core.kernel.Jobs.*;
import static dev.aivillages.core.kernel.Outcomes.*;
import static dev.aivillages.core.kernel.PlacementTestSupport.*;
import static org.junit.jupiter.api.Assertions.*;
final class PlacementJobLifecycleTest {
    @TempDir Path directory;
    static final class Scene {
        final JobLifecycleStoreTest.Memory disk=new JobLifecycleStoreTest.Memory(OWNER.scope().worldId());
        final JobLifecycleStore jobs=store(disk.state);
        JobLifecycleStore store(Snapshot initial){return new JobLifecycleStore(initial,disk,JobLifecycleStore.privateJobs((a,c)->a.equals(ACTOR)&&c.equals(OWNER)),c->{},PlanningGoals.catalog(),JobLifecycleStoreTest.environment(),CLOCK,Settings.defaults(),false);}
        Job start(){UUID id=UUID.randomUUID();var b=bound(1);assertTrue(jobs.create(id,id,b.request(),OWNER,b.observation(),OakPlankProduction.executionLimits(1000).total(),List.of()).accepted());jobs.tick();var j=jobs.query(id,OWNER);var ref=new ArtifactRef(CraftingTablePlacement.ID,"c".repeat(64));assertTrue(jobs.assign(id,j.guard(),UUID.randomUUID(),ACTOR,ref,List.of(ref),j.allowance(),OWNER).accepted());jobs.tick();return jobs.query(id,OWNER);}
        List<ResourceDelivery.Receipt> receipts(Job j,boolean placed){var d=new Driver();if(placed)d.place();else d.prepare();var run=j.current().executions().getFirst().runId();return d.receipts.stream().map(r->new ResourceDelivery.Receipt(r.receiptId(),OWNER,run,r.operationId(),r.batchId(),ACTOR,r.source(),r.destination(),r.item(),r.stage(),r.quantity(),r.sourceBlock(),r.dropIds(),null,r.placement())).toList();}
        Job report(Job j,List<ResourceDelivery.Receipt> receipts,boolean terminal){var a=j.current();long effects=receipts.size();var outcome=terminal?new Execution(ExecutionStatus.SUCCEEDED,null,effects,new EvidenceRef(a.id().toString(),"table-placement:1",OWNER.scope().domainId().toString())):null;var change=jobs.recordExecutionResult(j.id(),j.guard(),new Report(a.id(),a.generation(),effects,Map.of(Budgets.Kind.COMMITTED_EFFECTS,effects),List.of(),outcome,receipts),OWNER);assertTrue(change.accepted(),change.toString());jobs.tick();return jobs.query(j.id(),OWNER);}
    }
    @Test void exactPlacementCompletesThroughExistingJobs(){var s=new Scene();var j=s.start();j=s.report(j,s.receipts(j,true),true);assertEquals(State.SUCCEEDED,j.state());assertEquals(1,j.fulfilled());assertEquals(2,j.effects());}
    @Test void withdrawalDoesNotFulfillPlace(){var s=new Scene();var j=s.start();j=s.report(j,s.receipts(j,false),false);assertEquals(0,j.fulfilled());assertEquals(1,j.effects());}
    @Test void strictNewReceiptRoundTripRetainsOldHeaderAndLegacyEncoding()throws Exception{var s=new Scene();var j=s.start();s.report(j,s.receipts(j,true),true);Snapshot persisted;try(var journal=JobJournal.open(directory,OWNER.scope().worldId())){persisted=new Snapshot(s.disk.state.worldId(),journal.snapshot().revision()+1,s.disk.state.jobs(),s.disk.state.allocations());journal.replace(journal.snapshot(),persisted);}var raw=Files.readString(directory.resolve(JobJournal.WORLD_RELATIVE_PATH).resolve("state.jsonl"));assertTrue(raw.contains("\"placement\"")&&raw.contains("\"schema\":4"));assertEquals(2L,StrictJson.object(raw.lines().findFirst().orElseThrow()).get("schema"));try(var journal=JobJournal.open(directory,OWNER.scope().worldId())){assertFalse(journal.readOnly());assertEquals(persisted,journal.snapshot());}var old=new JobLifecycleStoreTest.Scene();var wheat=old.assign(old.create(1));wheat=old.report(wheat,1,ExecutionStatus.SUCCEEDED);String row=JobCodec.job(wheat);assertEquals(1L,StrictJson.object(row).get("schema"));assertFalse(row.contains("placement"));assertEquals(wheat,JobCodec.job(StrictJson.object(row)));}
    @Test void unfinishedWithdrawRestoresInterruptedWithNoCredit(){var s=new Scene();var j=s.start();var receipts=s.receipts(j,false);j=s.report(j,receipts,false);var reopened=s.store(s.disk.state);reopened.tick();var r=reopened.query(j.id(),OWNER);assertEquals(State.INTERRUPTED,r.state());assertTrue(r.current().uncertain());assertEquals(receipts,r.current().resourceReceipts());assertEquals(0,r.fulfilled());}
    @Test void actualPlacedEffectBeforeTerminalRestoresVisibleWithoutReplay(){var s=new Scene();var j=s.start();var receipts=s.receipts(j,true);j=s.report(j,receipts,false);var reopened=s.store(s.disk.state);reopened.tick();var r=reopened.query(j.id(),OWNER);assertEquals(State.INTERRUPTED,r.state());assertEquals(receipts,r.current().resourceReceipts());assertEquals(1,r.fulfilled());assertEquals(2,r.effects());}
    @Test void foreignReportCannotCreditPlacement(){var s=new Scene();var j=s.start();var foreign=JobLifecycleStoreTest.owner(OWNER.scope().worldId());var a=j.current();assertFalse(s.jobs.recordExecutionResult(j.id(),j.guard(),new Report(a.id(),a.generation(),0,Map.of(),List.of(),null),foreign).accepted());assertEquals(0,s.jobs.query(j.id(),OWNER).fulfilled());}
    @Test void phaseChildIsOwnedAndHasZeroInference(){var s=new CompositionOwnerTest.Scene();var root=s.root();var c=s.jobs.admitFacilityChild(root.id(),root.guard(),true,s.f.ref,null,s.f.owner);assertTrue(c.accepted(),c.toString());s.ack();var child=s.jobs.query(c.job().id(),s.f.owner);assertEquals(root.id(),child.parent());assertNull(child.preparation().method());assertFalse(s.jobs.materialReady(child));assertEquals(0,child.allowance().maximum(Budgets.Kind.INPUT_BYTES));assertTrue(s.root().dependencies().contains(child.id()));assertEquals(0,s.root().fulfilled());}
    @Test void staleGuardCannotPublishFacilityChild(){var s=new CompositionOwnerTest.Scene();var r=s.root();assertFalse(s.jobs.admitFacilityChild(r.id(),new Guard(r.revision()+1,r.generation()),true,s.f.ref,null,s.f.owner).accepted());assertTrue(s.root().children().isEmpty());}
    @Test void facilityStageRecoveryInterruptsParentAndChild(){var s=new CompositionOwnerTest.Scene();var r=s.root();var c=s.jobs.admitFacilityChild(r.id(),r.guard(),true,s.f.ref,null,s.f.owner);assertTrue(c.accepted());s.ack();var reopened=s.store(s.disk.state);reopened.tick();assertEquals(State.INTERRUPTED,reopened.query(r.id(),s.f.owner).state());assertEquals(State.INTERRUPTED,reopened.query(c.job().id(),s.f.owner).state());}
}
